class Solution { public long maxSpending(int[][] values){PriorityQueue<int[]> heap=new PriorityQueue<>((a,b)->Integer.compare(a[0],b[0]));for(int row=0;row<values.length;row++){int column=values[row].length-1;heap.offer(new int[]{values[row][column],row,column});}long answer=0,day=1;while(!heap.isEmpty()){int[] item=heap.poll();answer+=day++*item[0];if(item[2]>0){int column=item[2]-1;heap.offer(new int[]{values[item[1]][column],item[1],column});}}return answer;} }
